CREATE TABLE "bridge".query_event (
  event_id uuid NOT NULL,
  started_at timestamptz NOT NULL,
  finished_at timestamptz NOT NULL,
  received_at timestamptz NOT NULL DEFAULT now(),
  contract_version smallint NOT NULL,
  studio_instance text NOT NULL CHECK (char_length(studio_instance) BETWEEN 1 AND 128),
  subject text NOT NULL CHECK (char_length(subject) BETWEEN 1 AND 512),
  username text CHECK (char_length(username) <= 320),
  session_role text NOT NULL CHECK (session_role IN ('admin','user')),
  connection_id text NOT NULL CHECK (char_length(connection_id) BETWEEN 1 AND 64),
  connection_name text CHECK (char_length(connection_name) <= 128),
  engine text CHECK (engine ~ '^[a-z][a-z0-9]{0,31}$'),
  access_level text CHECK (access_level IN ('read','write')),
  source text NOT NULL CHECK (source ~ '^[a-z][a-z-]{0,31}$'),
  statement_type text NOT NULL CHECK (statement_type IN ('SELECT','INSERT','UPDATE','DELETE','DDL','OTHER')),
  explain text CHECK (explain IN ('plan','analyze')),
  statement_capture text NOT NULL CHECK (statement_capture IN ('none','redacted','full')),
  statement text CHECK (octet_length(statement) <= 65536),
  statement_truncated boolean NOT NULL DEFAULT false,
  statement_fingerprint text CHECK (statement_fingerprint ~ '^[0-9a-f]{64}$'),
  unit_index integer CHECK (unit_index >= 0),
  row_count bigint CHECK (row_count >= 0),
  duration_ms integer NOT NULL CHECK (duration_ms >= 0),
  status text NOT NULL CHECK (status IN ('success','error','cancelled','refused')),
  error_code text CHECK (char_length(error_code) <= 64),
  error_message text CHECK (char_length(error_message) <= 1000),
  correlation_id text CHECK (char_length(correlation_id) <= 128),
  transaction_id text CHECK (char_length(transaction_id) <= 128),
  transaction_outcome text CHECK (transaction_outcome ~ '^[a-z][a-z-]{0,31}$'),
  client_ip inet,
  PRIMARY KEY (event_id),
  CONSTRAINT query_event_time_order CHECK (finished_at >= started_at),
  CONSTRAINT query_event_not_future CHECK (started_at <= received_at + interval '5 minutes'),
  CONSTRAINT query_event_capture_none CHECK (statement_capture <> 'none' OR (statement IS NULL AND statement_fingerprint IS NULL)),
  CONSTRAINT query_event_error_text_full_only CHECK (statement_capture = 'full' OR error_message IS NULL),
  CONSTRAINT query_event_resolved CHECK (status = 'refused' OR (engine IS NOT NULL AND access_level IS NOT NULL))
);
GRANT SELECT ON TABLE "bridge".query_event TO libredb_platform;
CREATE VIEW "bridge".query_events_v1 WITH (security_barrier = true, security_invoker = false) AS SELECT event_id, started_at, finished_at, contract_version, studio_instance, subject, username, session_role, connection_id, connection_name, engine, access_level, source, statement_type, explain, statement_capture, statement, statement_truncated, statement_fingerprint, unit_index, row_count, duration_ms, status, error_code, error_message, correlation_id, transaction_id, transaction_outcome, client_ip FROM "bridge".query_event WHERE contract_version = 1 WITH LOCAL CHECK OPTION;
